-- f-jsh-content · 3 of 4: JSH's calendars and events from its website.
--
-- The six public calendars on https://www.jainsocietyhouston.org/jsheventcalendar
-- (snapshot 2026-09-25 in supabase/data/jsh-calendar, README there):
--   JSH Events        -> the events layer, and one event per date (past = completed), venue from the location
--   JSH Pathshala     -> the Pathshala layer
--   Jain Panchang     -> a tithi (panchang) layer: Aatham, Chaudas, Pancham and parva days
--   Bhaktamber, SHINE -> their own layers; weekly sessions expanded for the window, Zoom links in the notes
--   FBISD             -> "School calendar (FBISD)", a school-district layer
-- Each layer is subscribed to its public link, so the daily refresh (0510,
-- calendar.refresh_feeds) keeps it current. The dates below are generated by
-- worker/scripts/jsh-calendar-seed.ts with the subscription's own parser and
-- window, so they are what a subscription produces; a worker test fails if
-- they drift. An office reminder on the public events calendar is left out.
--
-- Nothing is added twice: layers are found by key (JSH's existing "events" and
-- "pathshala" layers are reused), entries by their calendar UID. The time zone
-- of timed entries is the organization's (America/Chicago for JSH).
-- app.seed_jsh_calendars does nothing unless the organization exists; it is
-- also called at the end of seed.sql (see 0511).
set client_min_messages = warning;

-- A layer for a seeded subscription: found by key (or, for the one-per-organization
-- kinds events and pathshala, by kind), else created; then subscribed to its link.
create or replace function app.calendar_seed_layer(p_center uuid, p_key text, p_kind text, p_name text, p_color text,
                                                   p_default_on boolean, p_url text, p_creates_events boolean)
returns uuid language plpgsql security definer set search_path = app, public, extensions as $$
declare v_id uuid;
begin
  select id into v_id from app.calendar_layers where center_id = p_center and key = p_key order by id limit 1;
  if v_id is null and p_kind in ('events','pathshala') then
    select id into v_id from app.calendar_layers where center_id = p_center and kind = p_kind order by id limit 1;
  end if;
  if v_id is null then
    insert into app.calendar_layers (center_id, key, name, kind, default_on, color)
    values (p_center, p_key, p_name, p_kind, p_default_on, p_color) returning id into v_id;
  end if;
  update app.calendar_layers
     set source_url = p_url, feed_subscribed = true, feed_creates_events = p_creates_events
   where id = v_id and (source_url is distinct from p_url or not feed_subscribed or feed_creates_events is distinct from p_creates_events);
  return v_id;
end $$;

-- Apply seeded entries exactly as a refresh would, and stamp the layer as refreshed.
create or replace function app.calendar_seed_apply(p_layer uuid, p_entries jsonb, p_keep_before date, p_feed jsonb)
returns jsonb language plpgsql security definer set search_path = app, public, extensions as $$
declare v jsonb;
begin
  v := app.calendar_feed_apply(p_layer, p_entries, p_keep_before);
  update app.calendar_layers
     set feed_status = 'ok', feed_synced_at = coalesce(feed_synced_at, now()), feed_checked_at = coalesce(feed_checked_at, now()),
         feed_error = null, feed_result = v || jsonb_build_object('feed', p_feed)
   where id = p_layer and (feed_status <> 'ok' or feed_synced_at is null);
  return v;
end $$;

create or replace function app.seed_jsh_calendars(p_center uuid) returns jsonb
language plpgsql security definer set search_path = app, public, extensions as $fn$
declare v_layer uuid; v_out jsonb := '{}'::jsonb;
begin
  if p_center is null or not exists (select 1 from app.centers where id = p_center) then return v_out; end if;
  perform app.set_audit_context('JSH sandbox content: calendars from jainsocietyhouston.org (owner, 2026-09-25)');
-- BEGIN jsh calendar seed (generated by worker/scripts/jsh-calendar-seed.ts from supabase/data/jsh-calendar)
  -- JSH Events (jsh-events.ics): 16 dates
  v_layer := app.calendar_seed_layer(p_center, 'events', 'events', 'JSH Events', '#7A2E1F', true, 'https://calendar.google.com/calendar/ical/c_b050cd4bd2d10bef85e59c50531e6db289c6c2c366391ee13c39505756b114d8%40group.calendar.google.com/public/basic.ics', true);
  v_out := v_out || jsonb_build_object('events', app.calendar_seed_apply(v_layer, $json$[
